// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/schedules", wrapper.ListSchedules)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/schedules", wrapper.CreateSchedule)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/schedules/{id}", wrapper.GetSchedule)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/occurrences", wrapper.ListOccurrences)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/occurrences/{id}/realize", wrapper.RealizeOccurrence)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/occurrences/{id}/skip", wrapper.SkipOccurrence)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/occurrences/{id}/move", wrapper.MoveOccurrence)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/schedules/{id}/terms", wrapper.ChangeScheduleTerms)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/schedules/{id}/pauses", wrapper.PauseSchedule)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/schedules/{id}/end", wrapper.EndSchedule)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/budgets", wrapper.ListBudgets)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/budgets", wrapper.CreateBudget)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/budgets/{id}", wrapper.GetBudget)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/budgets/{id}/amounts", wrapper.AddBudgetAmount)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/budgets/{id}/progress", wrapper.GetBudgetProgress)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/goals", wrapper.ListGoals)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/goals", wrapper.CreateGoal)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/goals/{id}", wrapper.GetGoal)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/accounts/{id}/projection", wrapper.GetProjection)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/commitments", wrapper.GetCommitted)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/occurrences/{id}/unrealize", wrapper.UnrealizeOccurrence)

	return m
}

