// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetProjection Projected balance of a balance account to a date after today, at most today + 12 months (P7 amendment A56).
	// (GET /accounts/{id}/projection)
	GetProjection(ctx context.Context, request GetProjectionRequestObject) (GetProjectionResponseObject, error)
	// ListBudgets Budgets in creation order.
	// (GET /budgets)
	ListBudgets(ctx context.Context, request ListBudgetsRequestObject) (ListBudgetsResponseObject, error)
	// CreateBudget Create the monthly budget of a category (P7 amendment A54; 409 budget_exists when it has one).
	// (POST /budgets)
	CreateBudget(ctx context.Context, request CreateBudgetRequestObject) (CreateBudgetResponseObject, error)
	// GetBudget A budget with its amounts by month.
	// (GET /budgets/{id})
	GetBudget(ctx context.Context, request GetBudgetRequestObject) (GetBudgetResponseObject, error)
	// AddBudgetAmount Set the amount from a month on, after the latest one (T09).
	// (POST /budgets/{id}/amounts)
	AddBudgetAmount(ctx context.Context, request AddBudgetAmountRequestObject) (AddBudgetAmountResponseObject, error)
	// GetBudgetProgress Planned, carried, spent and available amounts of a month, accrual view (P7 amendment A54).
	// (GET /budgets/{id}/progress)
	GetBudgetProgress(ctx context.Context, request GetBudgetProgressRequestObject) (GetBudgetProgressResponseObject, error)
	// GetCommitted Installments and expected bills, subscriptions and savings committed in a month (P7 amendment A57).
	// (GET /commitments)
	GetCommitted(ctx context.Context, request GetCommittedRequestObject) (GetCommittedResponseObject, error)
	// ListGoals Goals in creation order, with their progress today.
	// (GET /goals)
	ListGoals(ctx context.Context, request ListGoalsRequestObject) (ListGoalsResponseObject, error)
	// CreateGoal Create a target balance over balance accounts by a date (P7 amendment A55).
	// (POST /goals)
	CreateGoal(ctx context.Context, request CreateGoalRequestObject) (CreateGoalResponseObject, error)
	// GetGoal A goal with its progress today.
	// (GET /goals/{id})
	GetGoal(ctx context.Context, request GetGoalRequestObject) (GetGoalResponseObject, error)
	// ListOccurrences Occurrences with expected date in [from, to], at most 366 days, by date.
	// (GET /occurrences)
	ListOccurrences(ctx context.Context, request ListOccurrencesRequestObject) (ListOccurrencesResponseObject, error)
	// MoveOccurrence Move an expected occurrence to another date; terms changes never regenerate it (P7 amendment A52).
	// (POST /occurrences/{id}/move)
	MoveOccurrence(ctx context.Context, request MoveOccurrenceRequestObject) (MoveOccurrenceResponseObject, error)
	// RealizeOccurrence Link a transaction to an expected occurrence; ledger changes never release it (P7 amendment A51).
	// (POST /occurrences/{id}/realize)
	RealizeOccurrence(ctx context.Context, request RealizeOccurrenceRequestObject) (RealizeOccurrenceResponseObject, error)
	// SkipOccurrence Skip an expected occurrence (T03; 409 occurrence_closed otherwise).
	// (POST /occurrences/{id}/skip)
	SkipOccurrence(ctx context.Context, request SkipOccurrenceRequestObject) (SkipOccurrenceResponseObject, error)
	// UnrealizeOccurrence Release a realized occurrence (409 occurrence_closed when it is not realized).
	// (POST /occurrences/{id}/unrealize)
	UnrealizeOccurrence(ctx context.Context, request UnrealizeOccurrenceRequestObject) (UnrealizeOccurrenceResponseObject, error)
	// ListSchedules Schedules in creation order.
	// (GET /schedules)
	ListSchedules(ctx context.Context, request ListSchedulesRequestObject) (ListSchedulesResponseObject, error)
	// CreateSchedule Create a schedule and generate its occurrences up to today + 12 months (P7 amendments A46-A49).
	// (POST /schedules)
	CreateSchedule(ctx context.Context, request CreateScheduleRequestObject) (CreateScheduleResponseObject, error)
	// GetSchedule A schedule with its terms versions and pauses.
	// (GET /schedules/{id})
	GetSchedule(ctx context.Context, request GetScheduleRequestObject) (GetScheduleResponseObject, error)
	// EndSchedule Produce no occurrence on or after a date; expected ones are removed, realized ones stay (P7 amendment A52).
	// (POST /schedules/{id}/end)
	EndSchedule(ctx context.Context, request EndScheduleRequestObject) (EndScheduleResponseObject, error)
	// PauseSchedule Suppress the dates in [from, to] (P7 amendment A52).
	// (POST /schedules/{id}/pauses)
	PauseSchedule(ctx context.Context, request PauseScheduleRequestObject) (PauseScheduleResponseObject, error)
	// ChangeScheduleTerms Add a terms version effective from a date after the latest one (T09; P7 amendments A49, A52).
	// (POST /schedules/{id}/terms)
	ChangeScheduleTerms(ctx context.Context, request ChangeScheduleTermsRequestObject) (ChangeScheduleTermsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

